class SearchResult:
    """One page of matches plus the numbers the screen needs."""

    items: list[Project]
    total: int
    page: int
    page_size: int

    @property
    def pages(self) -> int:
        """Return how many pages the total fills, at least one."""
        if self.page_size <= 0:
            return 1
        return max(1, -(-self.total // self.page_size))

